import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';
import Lottie from 'lottie-react';
import DOMPurify from 'dompurify';
import './Category.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

/**
 * Category Metadata Configuration
 * Maps each category to its display properties, colors, icons,
 * video backgrounds, and Lottie animation sources.
 * 
 * Security: No user input is used in these configurations.
 */
const categoryMeta = {
  dry: {
    title: 'Dry Items (Namkeen & Farsan)',
    icon: '🥨',
    desc: 'Crispy, crunchy savory snacks perfect for any time of the day. All our dry items are prepared fresh with traditional recipes.',
    color: '#D44444',
    gradient: 'from-red-600 to-red-800',
    bgLight: 'bg-orange-50',
    cardBg: 'from-orange-50 to-amber-50',
    videoPlaceholder: 'https://cdn.coverr.co/videos/coverr-cooking-snacks-in-kitchen-5690/1080p.mp4',
    lottieUrl: 'https://assets10.lottiefiles.com/packages/lf20_w98qte06.json'
  },
  sweet: {
    title: 'Sweet Items (Longer Shelf Life)',
    icon: '🍬',
    desc: 'Traditional Maharashtrian sweets that stay fresh longer. Perfect for gifting, celebrations, and festive occasions.',
    color: '#FF6B35',
    gradient: 'from-orange-500 to-red-600',
    bgLight: 'bg-amber-50',
    cardBg: 'from-yellow-50 to-orange-50',
    videoPlaceholder: 'https://cdn.coverr.co/videos/coverr-pouring-honey-on-pancakes-2529/1080p.mp4',
    lottieUrl: 'https://assets2.lottiefiles.com/packages/lf20_ysas4vcp.json'
  },
  wet: {
    title: 'Wet/Fresh Sweets (Shorter Shelf Life)',
    icon: '🍮',
    desc: 'Freshly made premium sweets, best enjoyed within days. These require advance booking for guaranteed freshness.',
    color: '#8B4513',
    gradient: 'from-amber-700 to-amber-900',
    bgLight: 'bg-amber-50',
    cardBg: 'from-amber-50 to-yellow-50',
    videoPlaceholder: 'https://cdn.coverr.co/videos/coverr-making-dessert-in-kitchen-5668/1080p.mp4',
    lottieUrl: 'https://assets1.lottiefiles.com/packages/lf20_hl5imhpf.json'
  }
};

/**
 * Category Tabs Component
 * Renders clickable tabs for filtering products by category
 */
function CategoryTabs({ activeCategory, onCategoryChange }) {
  const tabs = [
    { key: 'dry', label: '🥨 Dry Items', icon: '🥨' },
    { key: 'sweet', label: '🍬 Sweets', icon: '🍬' },
    { key: 'wet', label: '🍮 Fresh Sweets', icon: '🍮' }
  ];

  return (
    <div className="category-tabs flex flex-wrap gap-3 justify-center mb-10">
      {tabs.map(tab => (
        <button
          key={tab.key}
          onClick={() => onCategoryChange(tab.key)}
          className={`
            px-6 py-3 rounded-full font-semibold text-sm
            transition-all duration-300 ease-out
            shadow-md hover:shadow-xl
            transform hover:scale-105 active:scale-95
            ${activeCategory === tab.key
              ? 'bg-gradient-to-r from-red-700 to-red-500 text-white shadow-lg scale-105'
              : 'bg-white text-gray-700 hover:bg-red-50 hover:text-red-600'
            }
          `}
        >
          <span className="flex items-center gap-2">
            <span className="text-lg">{tab.icon}</span>
            {tab.label}
          </span>
        </button>
      ))}
    </div>
  );
}

/**
 * ProductCard Component
 * Renders an individual product with hover animations, image placeholder,
 * price display, weight options, and add-to-cart functionality.
 * 
 * Security: All product descriptions are sanitized with DOMPurify 
 * before rendering via dangerouslySetInnerHTML to prevent XSS.
 */
function ProductCard({ product, meta, onAddToCart }) {
  const [isHovered, setIsHovered] = useState(false);
  const [addedToCart, setAddedToCart] = useState(false);

  // Sanitize description to prevent XSS attacks
  const sanitizedDesc = DOMPurify.sanitize(product.description || '');

  const handleAddToCart = () => {
    onAddToCart(product);
    setAddedToCart(true);
    setTimeout(() => setAddedToCart(false), 1500);
  };

  return (
    <div
      className={`
        product-card group
        bg-white rounded-2xl overflow-hidden
        shadow-lg hover:shadow-2xl
        transform transition-all duration-500 ease-out
        ${isHovered ? 'scale-[1.03] -translate-y-2' : 'scale-100'}
      `}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Product Image Area with Gradient Overlay */}
      <div className="relative h-52 overflow-hidden">
        <div className={`w-full h-full bg-gradient-to-br ${meta.cardBg} flex items-center justify-center`}>
          <span className="text-7xl opacity-60 group-hover:scale-110 transition-transform duration-500">
            {meta.icon}
          </span>
        </div>
        
        {/* Price Badge */}
        <div className={`
          absolute top-3 right-3 
          bg-gradient-to-r ${meta.gradient} 
          text-white px-4 py-1.5 rounded-full 
          text-sm font-bold shadow-lg 
          transform transition-all duration-300 
          ${isHovered ? 'scale-110' : ''}
        `}>
          ₹{product.price}/{product.unit}
        </div>

        {/* Availability Badge */}
        {product.is_regular ? (
          <div className="absolute top-3 left-3 bg-green-500 text-white px-3 py-1 rounded-full text-xs font-semibold shadow-md">
            ✅ In Stock
          </div>
        ) : (
          <div className="absolute top-3 left-3 bg-yellow-500 text-white px-3 py-1 rounded-full text-xs font-semibold shadow-md animate-pulse">
            ⏰ Advance Booking
          </div>
        )}

        {/* Hover Overlay */}
        <div className={`
          absolute inset-0 bg-black/10 
          transition-opacity duration-300 
          ${isHovered ? 'opacity-100' : 'opacity-0'}
        `}></div>
      </div>

      {/* Product Details */}
      <div className="p-5">
        <h3 className="text-lg font-bold text-gray-800 mb-1.5 group-hover:text-red-700 transition-colors duration-300">
          {product.name}
        </h3>
        <p 
          className="text-sm text-gray-500 mb-3 line-clamp-2"
          dangerouslySetInnerHTML={{ __html: sanitizedDesc }}
        />
        
        {/* Weight/Size Options */}
        <div className="flex gap-2 mb-4">
          <span className="px-3 py-1 bg-gray-100 rounded-full text-xs font-medium text-gray-600">1 KG</span>
          <span className="px-3 py-1 bg-gray-100 rounded-full text-xs font-medium text-gray-600">500 GM</span>
          <span className="px-3 py-1 bg-gray-100 rounded-full text-xs font-medium text-gray-600">250 GM</span>
        </div>

        {/* Add to Cart Button with Animation */}
        <button
          className={`
            w-full py-2.5 rounded-xl font-semibold text-sm
            transition-all duration-300 ease-out
            ${addedToCart 
              ? 'bg-green-500 text-white scale-105' 
              : isHovered 
                ? `bg-gradient-to-r ${meta.gradient} text-white shadow-lg scale-[1.02]` 
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }
          `}
          onClick={handleAddToCart}
          disabled={addedToCart}
        >
          <span className="flex items-center justify-center gap-2">
            {addedToCart ? '✅ Added!' : '🛒 Add to Cart'}
            {isHovered && !addedToCart && <span className="inline-block animate-bounce">→</span>}
          </span>
        </button>
      </div>
    </div>
  );
}

/**
 * VideoBackground Component
 * Displays an HTML5 video as a background element for the hero section.
 * The video is muted, looped, and plays inline for autoplay support.
 * 
 * Video files should be kept under 2MB for optimal performance.
 */
function VideoBackground({ src, fallbackColor }) {
  const videoRef = useRef(null);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => {
        // Autoplay was prevented, fallback to static background
        console.log('Video autoplay prevented, using fallback');
      });
    }
  }, [src]);

  return (
    <div className="absolute inset-0 overflow-hidden">
      <video
        ref={videoRef}
        autoPlay
        muted
        loop
        playsInline
        className="w-full h-full object-cover opacity-30"
        style={{ filter: 'blur(2px)' }}
      >
        <source src={src} type="video/mp4" />
        Your browser does not support the video tag.
      </video>
      <div className={`absolute inset-0 ${fallbackColor} mix-blend-multiply`}></div>
    </div>
  );
}

/**
 * LottieAnimation Component
 * Fetches Lottie JSON from URL and renders animation using lottie-react.
 * Falls back gracefully if the animation fails to load.
 */
function LottieAnimation({ animationUrl, className = '' }) {
  const [animationData, setAnimationData] = useState(null);
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    if (!animationUrl) return;
    fetch(animationUrl)
      .then(res => res.json())
      .then(data => setAnimationData(data))
      .catch(() => setHasError(true));
  }, [animationUrl]);

  if (hasError || !animationData) {
    return (
      <div className={`flex items-center justify-center ${className}`}>
        <span className="text-4xl animate-bounce">🚚</span>
      </div>
    );
  }

  return (
    <div className={className}>
      <Lottie
        animationData={animationData}
        loop={true}
        autoplay={true}
        style={{ width: '100%', height: '100%' }}
      />
    </div>
  );
}

/**
 * Category Page - Main Component
 * Displays an interactive product catalog with category filtering,
 * video backgrounds, Lottie animations, and responsive product cards.
 * 
 * Data is fetched from the backend REST API and distributed
 * across the appropriate category views.
 */
function Category({ addToCart }) {
  const { category } = useParams();
  const [products, setProducts] = useState([]);
  const [allProducts, setAllProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState(category || 'dry');
  const [addedMsg, setAddedMsg] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const meta = categoryMeta[activeCategory] || categoryMeta.dry;

  useEffect(() => {
    if (category && categoryMeta[category]) {
      setActiveCategory(category);
    }
  }, [category]);

  useEffect(() => {
    fetchAllProducts();
  }, []);

  /**
   * Fetch all products from the backend API
   * This allows client-side filtering without additional API calls
   */
  const fetchAllProducts = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_URL}/api/products/`);
      setAllProducts(res.data.products);
    } catch (err) {
      console.error('Error fetching products:', err);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Filter products based on active category and search query
   */
  useEffect(() => {
    let filtered = allProducts.filter(p => p.category === activeCategory);
    
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(p => 
        p.name.toLowerCase().includes(query) || 
        (p.description && p.description.toLowerCase().includes(query))
      );
    }
    
    setProducts(filtered);
  }, [activeCategory, allProducts, searchQuery]);

  const handleCategoryChange = (newCategory) => {
    setActiveCategory(newCategory);
    setSearchQuery('');
  };

  const handleAddToCart = (product) => {
    addToCart(product);
    setAddedMsg(product.name);
    setTimeout(() => setAddedMsg(''), 2000);
  };

  if (loading) {
    return (
      <div className="category-loading min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-red-50 to-orange-50">
        <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-gray-600 text-lg font-medium animate-pulse">Loading our delicious menu...</p>
      </div>
    );
  }

  return (
    <div className="category-page bg-gradient-to-br from-gray-50 to-orange-50 min-h-screen">
      {/* Hero Section with Video Background */}
      <div className="relative overflow-hidden bg-gradient-to-r from-red-800 via-red-700 to-red-600">
        <VideoBackground src={meta.videoPlaceholder} fallbackColor="bg-gradient-to-r from-red-800 to-red-600" />
        
        <div className="relative z-10 container mx-auto px-4 py-16 md:py-24">
          {/* Breadcrumb */}
          <Link to="/" className="inline-flex items-center text-white/80 hover:text-white text-sm mb-6 transition-colors">
            <span className="mr-1">←</span> Back to Home
          </Link>

          <div className="flex flex-col md:flex-row items-center gap-8">
            {/* Category Icon */}
            <div className="flex-shrink-0 w-24 h-24 md:w-32 md:h-32 bg-white/20 backdrop-blur rounded-full flex items-center justify-center animate-float">
              <span className="text-6xl md:text-7xl">{meta.icon}</span>
            </div>

            {/* Category Info */}
            <div className="text-center md:text-left">
              <h1 className="text-3xl md:text-5xl font-bold text-white mb-4 font-serif">
                {meta.title}
              </h1>
              <p className="text-white/80 text-lg max-w-2xl leading-relaxed">
                {meta.desc}
              </p>
              
              {/* Stats */}
              <div className="flex flex-wrap gap-6 mt-6 justify-center md:justify-start">
                <div className="text-center">
                  <div className="text-2xl font-bold text-yellow-400">{products.length}</div>
                  <div className="text-white/70 text-sm">Items Available</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-yellow-400">₹{Math.min(...products.map(p => p.price), 0)}</div>
                  <div className="text-white/70 text-sm">Starting Price</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-yellow-400">🚚</div>
                  <div className="text-white/70 text-sm">Free Delivery*</div>
                </div>
              </div>
            </div>
          </div>

          {/* Lottie Delivery Animation */}
          <div className="absolute right-4 bottom-4 w-24 h-24 md:w-32 md:h-32 opacity-60">
            <LottieAnimation animationUrl={meta.lottieUrl} className="w-full h-full" />
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="container mx-auto px-4 py-8">
        {/* Category Tabs */}
        <CategoryTabs activeCategory={activeCategory} onCategoryChange={handleCategoryChange} />

        {/* Advance Booking Notice for Fresh Sweets */}
        {activeCategory === 'wet' && (
          <div className="mb-8 p-4 bg-gradient-to-r from-yellow-50 to-amber-50 border border-yellow-200 rounded-2xl flex items-center gap-3 animate-pulse">
            <span className="text-2xl">⏰</span>
            <div>
              <p className="font-semibold text-amber-800">Advance Booking Required</p>
              <p className="text-sm text-amber-600">Fresh sweets require 1-2 days advance booking for guaranteed freshness</p>
            </div>
          </div>
        )}

        {/* Search Bar */}
        <div className="mb-8 max-w-md mx-auto">
          <div className="relative">
            <input
              type="text"
              placeholder="🔍 Search items..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full px-6 py-3 rounded-full border-2 border-gray-200 focus:border-red-500 focus:outline-none shadow-md bg-white/80 backdrop-blur transition-all duration-300"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
            )}
          </div>
        </div>

        {/* Products Grid */}
        {products.length === 0 ? (
          <div className="text-center py-20">
            <div className="text-6xl mb-4">📭</div>
            <h3 className="text-2xl font-bold text-gray-700 mb-2">No items found</h3>
            <p className="text-gray-500 mb-6">
              {searchQuery ? 'Try a different search term' : 'No products in this category yet'}
            </p>
            {searchQuery ? (
              <button
                onClick={() => setSearchQuery('')}
                className="px-6 py-3 bg-red-600 text-white rounded-full font-semibold hover:bg-red-700 transition-colors"
              >
                Clear Search
              </button>
            ) : (
              <Link to="/" className="px-6 py-3 bg-red-600 text-white rounded-full font-semibold hover:bg-red-700 transition-colors inline-block">
                Back to Home
              </Link>
            )}
          </div>
        ) : (
          <>
            {/* Section with Video Card */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 mb-12">
              {/* Lottie Animation Card - First Position */}
              <div className="bg-gradient-to-br from-red-50 to-orange-50 rounded-2xl p-6 flex flex-col items-center justify-center min-h-[300px] shadow-lg">
                <div className="w-32 h-32 mb-4">
                  <LottieAnimation animationUrl={meta.lottieUrl} className="w-full h-full" />
                </div>
                <h4 className="font-bold text-gray-700 text-center">Fresh Delivery</h4>
                <p className="text-sm text-gray-500 text-center mt-1">Straight from our kitchen to your door</p>
              </div>

              {/* Product Cards */}
              {products.slice(0, 3).map(product => (
                <ProductCard
                  key={product._id}
                  product={product}
                  meta={meta}
                  onAddToCart={handleAddToCart}
                />
              ))}

              {/* Video Background Card */}
              <div className="relative rounded-2xl overflow-hidden min-h-[300px] shadow-lg group">
                <video
                  autoPlay
                  muted
                  loop
                  playsInline
                  className="absolute inset-0 w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                >
                  <source src={meta.videoPlaceholder} type="video/mp4" />
                </video>
                <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent"></div>
                <div className="absolute bottom-0 left-0 right-0 p-6">
                  <span className="text-3xl mb-2 block">👨‍🍳</span>
                  <h4 className="text-white font-bold text-lg">Made with Love</h4>
                  <p className="text-white/80 text-sm">Traditional recipes passed down generations</p>
                </div>
              </div>
            </div>

            {/* Remaining Products Grid */}
            {products.length > 4 && (
              <>
                <h3 className="text-2xl font-bold text-gray-800 mb-6 font-serif">
                  More {meta.title.split('(')[0].trim()}
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {products.slice(4).map(product => (
                    <ProductCard
                      key={product._id}
                      product={product}
                      meta={meta}
                      onAddToCart={handleAddToCart}
                    />
                  ))}
                </div>
              </>
            )}
          </>
        )}

        {/* Delivery Info Section */}
        <div className="mt-12 bg-gradient-to-r from-red-600 to-red-800 rounded-2xl p-8 text-white">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-center">
            <div className="p-4">
              <span className="text-3xl block mb-2">🚚</span>
              <h4 className="font-bold text-lg mb-1">Free Delivery</h4>
              <p className="text-white/70 text-sm">On orders above ₹300 within 1km</p>
            </div>
            <div className="p-4">
              <span className="text-3xl block mb-2">📅</span>
              <h4 className="font-bold text-lg mb-1">Next-Day Delivery</h4>
              <p className="text-white/70 text-sm">For all regular items ordered before 6 PM</p>
            </div>
            <div className="p-4">
              <span className="text-3xl block mb-2">💳</span>
              <h4 className="font-bold text-lg mb-1">Secure Payment</h4>
              <p className="text-white/70 text-sm">COD & UPI payments accepted</p>
            </div>
          </div>
        </div>
      </div>

      {/* Toast Notification */}
      {addedMsg && (
        <div className="fixed bottom-6 right-6 bg-green-500 text-white px-6 py-3 rounded-xl shadow-2xl z-50 animate-slide-up flex items-center gap-2">
          <span>✅</span>
          <span className="font-medium">{addedMsg} added to cart!</span>
        </div>
      )}
    </div>
  );
}

export default Category;
